#pragma once

#include "language/language.hpp"

#include <cstdint>
#include <filesystem>
#include <string>
#include <vector>

namespace Project {

/** A source file held by the filesystem-free workspace compiler. */
struct SourceFile {
  std::filesystem::path path;
  std::string content;
};

/** A generated file that can be atomically written by a host. */
struct BuildArtifact {
  std::filesystem::path path;
  std::string content;
};

/** In-memory project input for deterministic compilation. */
struct Workspace {
  std::vector<SourceFile> files;
};

/** Result of compiling a workspace without performing filesystem effects. */
struct WorkspaceResult {
  bool success = false;
  std::vector<Language::Diagnostic> diagnostics;
  std::vector<BuildArtifact> artifacts;
};

/** Options controlling validation and filesystem-backed site builds. */
struct Options {
  std::filesystem::path root = ".";
  std::filesystem::path output;
  bool noWasm = false;
  bool strict = false;
  bool dryRun = false;
  bool quiet = false;
};

/** Result of an operation that writes or proposes project files. */
struct Result {
  bool success = false;
  std::vector<Language::Diagnostic> diagnostics;
  std::vector<std::filesystem::path> outputs;
};

/** Options for creating a starter project. */
struct InitOptions {
  std::filesystem::path root = ".";
  bool force = false;
};

/** Level of example project generated by the CLI. */
enum class ExampleProfile : std::uint8_t { Minimal, Complete };

/** Options for generating an example project. */
struct ExampleOptions {
  std::filesystem::path root = ".";
  ExampleProfile profile = ExampleProfile::Minimal;
  bool force = false;
};

/** Resolved URL plus its local target or a user-facing resolution error. */
struct UrlResolution {
  std::string value;
  std::filesystem::path target;
  std::string error;
  bool local = false;
};

/** Generate a minimal project without overwriting existing files. */
auto Init(const InitOptions &options) -> Result;
/** Generate the selected example project profile. */
auto Examples(const ExampleOptions &options) -> Result;
/** Compile in-memory files without reading or writing the filesystem. */
auto Compile(const Workspace &workspace, bool unsafeHtml = false) -> WorkspaceResult;
/** Validate a project and return stable diagnostics. */
auto Check(const std::filesystem::path &target, bool strict = false) -> Result;
/** Build a project into its configured output directory. */
auto Build(const Options &options) -> Result;
/** Report toolchain and project environment information. */
auto Doctor(const std::filesystem::path &root = ".") -> nlohmann::json;
/** Return the files used by the starter project template. */
auto BlankProjectFiles() -> std::vector<std::pair<std::filesystem::path, std::string>>;
/** Return files used by the selected example template. */
auto ExampleProjectFiles(ExampleProfile profile)
    -> std::vector<std::pair<std::filesystem::path, std::string>>;
/** Resolve a Markdown or asset URL relative to a project source file. */
auto ResolveUrl(const std::string &authored, const std::filesystem::path &source,
                const std::filesystem::path &pages, const std::string &basePath = "/",
                bool partial = false) -> UrlResolution;

} // namespace Project
